@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_clientbound_data_store_is_packet_330(version):
    assert version.PACKETS[330] is version.ClientboundDataStorePacket


def test_packet_330_is_not_in_v858():
    assert 330 not in v858.PACKETS


def test_packet_330_is_in_v859():
    assert 330 in v859.PACKETS


def test_v897_hands_packet_330_to_the_data_store_sync_packet():
    assert v897.PACKETS[330] is v897.DataStoreSyncPacket


def test_v898_hands_packet_330_to_the_clientbound_data_store_packet():
    assert v898.PACKETS[330] is v898.ClientboundDataStorePacket


def test_the_v897_sync_packet_tags_a_removal_with_case_one():
    assert bytes(V897_REMOVAL)[1] == 1


def test_a_v897_sync_packet_removal_round_trips():
    assert v897.DataStoreSyncPacket.from_bytes(bytes(V897_REMOVAL)) == V897_REMOVAL


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_store_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_store_decodes_from_its_golden(packet, golden):
    assert v2225.ClientboundDataStorePacket.from_bytes(golden) == packet


def test_an_unknown_dynamic_value_tag_is_rejected():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ClientboundDataStorePacket.from_bytes(UNKNOWN_VALUE_TAG)
